len_operator = len(operator)
len_operand = len(operand)
result = []
for i in range(len_operator - 1):
    op1 = operator[i]
    op2 = operator[i + 1]
    value1 = operand[i]
    value2 = operand[i + 1]
    if op1 == '+':
        result.append(value1 + value2)
    elif op1 == '-':
        result.append(value1 - value2)
    elif op1 == '*':
        result.append(value1 * value2)
    elif op1 == '/':
        result.append(value1 // value2)
    elif op1 == '**':
        result.append(value1 ** value2)
    else:
        raise ValueError("Invalid operator")
return result

